CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, created_at TEXT NOT NULL, expires_at TEXT, entered INTEGER NOT NULL DEFAULT 0, profile TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, id TEXT NOT NULL, slug TEXT NOT NULL, data TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(workspace,id), UNIQUE(workspace,slug));
CREATE TABLE IF NOT EXISTS variants (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, id TEXT NOT NULL, product_id TEXT NOT NULL, sku TEXT NOT NULL, name TEXT NOT NULL, finish TEXT NOT NULL, color TEXT NOT NULL, price INTEGER NOT NULL CHECK(price >= 0 AND price <= 100000000), stock INTEGER NOT NULL CHECK(stock >= 0 AND stock <= 100000), image TEXT NOT NULL, PRIMARY KEY(workspace,id), UNIQUE(workspace,sku), FOREIGN KEY(workspace,product_id) REFERENCES products(workspace,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cart_items (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, variant_id TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20), PRIMARY KEY(workspace,variant_id), FOREIGN KEY(workspace,variant_id) REFERENCES variants(workspace,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wishlist (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, product_id TEXT NOT NULL, PRIMARY KEY(workspace,product_id), FOREIGN KEY(workspace,product_id) REFERENCES products(workspace,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, reference TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('paid','processing','shipped','delivered','cancelled')), subtotal INTEGER NOT NULL CHECK(subtotal>=0), shipping INTEGER NOT NULL CHECK(shipping>=0), total INTEGER NOT NULL CHECK(total=subtotal+shipping), delivery TEXT NOT NULL, address TEXT NOT NULL, refund TEXT, UNIQUE(workspace,id));
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, snapshot TEXT NOT NULL, FOREIGN KEY(workspace,order_id) REFERENCES orders(workspace,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, key TEXT NOT NULL, input_hash TEXT NOT NULL, status TEXT NOT NULL, order_id TEXT, created_at TEXT NOT NULL, UNIQUE(workspace,key));
CREATE TABLE IF NOT EXISTS inquiries (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, email TEXT NOT NULL, topic TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL, fingerprint TEXT NOT NULL, UNIQUE(workspace,fingerprint));
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS addresses (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_workspace ON orders(workspace,created_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
INSERT OR IGNORE INTO migrations(version,applied_at) VALUES(1,datetime('now'));
